(2830814, 395361, 2780, '<td valign="top">I always thought electricity came under physics. I like the abstractness of this though, however I find the border distracting.</td>', 'I always thought electricity came under physics. I like the abstractness of this though, however I find the border distracting.', '2006-09-13 09:33:50.000000', NULL, 1),
(2830818, 394576, 2780, '<td valign="top">A real stretch on the challenge in my opinion, since light comes under physics, and bugs come under biology :P</td>', 'A real stretch on the challenge in my opinion, since light comes under physics, and bugs come under biology :P', '2006-09-13 09:35:20.000000', NULL, 1),
