(2831222, 392946, 51538, '<td valign="top">A little on the dark side for me but a good idea and a nice reaction going on there.</td>', 'A little on the dark side for me but a good idea and a nice reaction going on there.', '2006-09-13 11:24:26.000000', NULL, 1),
