(2836562, 395299, 35513, '<td valign="top">I really like the look of this shot...I think it makes a good abstract.  I''m not quite sure it fits "Chemistry" as much as I would like, but the shot comes off well.</td>', 'I really like the look of this shot...I think it makes a good abstract.  I''m not quite sure it fits "Chemistry" as much as I would like, but the shot comes off well.', '2006-09-15 00:01:52.000000', NULL, 1),
(2836565, 393202, 35513, '<td valign="top">The reddish cast to the photo is (I''m assuming) from the red lights of a developing room...but it''s a little hard for me to see the details of the photo at this size.</td>', 'The reddish cast to the photo is (I''m assuming) from the red lights of a developing room...but it''s a little hard for me to see the details of the photo at this size.', '2006-09-15 00:02:37.000000', NULL, 1),
(2836577, 393131, 35513, '<td valign="top">Interesting perspective, but I find the photo a little too soft/blurry for my tastes.</td>', 'Interesting perspective, but I find the photo a little too soft/blurry for my tastes.', '2006-09-15 00:05:39.000000', NULL, 1),
(2836583, 395284, 35513, '<td valign="top">Nice lighting and colors on this shot.  I find it a little distracting that the foreground flowers are out of focus, with the one on the rear left being what catches my eye.  I might prefer for the flowers in front to be the focus.</td>', 'Nice lighting and colors on this shot.  I find it a little distracting that the foreground flowers are out of focus, with the one on the rear left being what catches my eye.  I might prefer for the flowers in front to be the focus.', '2006-09-15 00:06:51.000000', NULL, 1),
