(2839744, 394813, 42495, '<td valign="top">Not sure if this is a reaction or a baked CD/DVD, but it''s very well done.  Colors are great.</td>', 'Not sure if this is a reaction or a baked CD/DVD, but it''s very well done.  Colors are great.', '2006-09-16 00:40:27.000000', NULL, 1),
(2839746, 395229, 42495, '<td valign="top">This is really funny and captures tedium in the chemistry classroom.  I won''t take off points for it, but those equations - oh my!</td>', 'This is really funny and captures tedium in the chemistry classroom.  I won''t take off points for it, but those equations - oh my!', '2006-09-16 00:42:34.000000', NULL, 1),
