(2848161, 395361, 65858, '<td valign="top">Nice idea.  Also reminds me of DNA in a cell.</td>', 'Nice idea.  Also reminds me of DNA in a cell.', '2006-09-19 18:11:25.000000', NULL, 1),
(2848167, 395107, 65858, '<td valign="top">Nice sharp focusing, simple background, stark color scheme.  The only thing is that the green seems grainy.</td>', 'Nice sharp focusing, simple background, stark color scheme.  The only thing is that the green seems grainy.', '2006-09-19 18:12:20.000000', NULL, 1),
